#!/usr/bin/env python3
"""
benchmark-prefill.py

Benchmark pre-fill (prompt processing) speed for **vLLM** *or* **Ollama**.

Each request asks the model to summarize a long document, but only the time
to the first output token (TTFT) is measured; generation is capped at 1 token.
Since TTFT is dominated by prompt processing for long prompts:

	prefill TPS = prompt_tokens / TTFT

Prompt tokens come from the backend (vLLM usage.prompt_tokens, Ollama
prompt_eval_count). For Ollama the server-side prompt_eval_duration is also
reported, which excludes HTTP/queueing overhead.

A random nonce is put at the very start of every prompt so prefix caching
cannot skip the prefill work.

The document is bundled (xz + base85, as comment lines) at the end of this file,
after the BUNDLE_MARKER line. It is unpacked into ./docs automatically when no
--doc is given and ./docs has no .md file, or explicitly with --extract-docs [DIR].
Keep the bundle last in the file; edit the code above it.
"""

import argparse, asyncio, glob, json, os, random, re, statistics, time
from typing import Any, Dict, Optional
import aiohttp
import requests


INSTRUCTION = "Summarize the following document in about 200 words."


def build_prompt(doc: str) -> str:
	# nonce first => the whole prompt differs from byte 0, defeating prefix caching
	return f"[request {random.getrandbits(48):012x}]\n{INSTRUCTION}\n\n<document>\n{doc}\n</document>\n\nSummary:"


BUNDLE_MARKER = "# ===== BUNDLED DOCUMENT (xz + base85), keep at end of file ====="


def extract_docs(dest: str = "docs") -> str:
	"""Unpack the document bundled at the end of this file into `dest`; returns its path."""
	import base64, lzma
	with open(os.path.abspath(__file__), encoding="utf-8") as fp:
		lines = fp.read().splitlines()
	i = lines.index(BUNDLE_MARKER)
	name = lines[i + 1].split(": ", 1)[1]
	data = lzma.decompress(base64.b85decode("".join(l[2:] for l in lines[i + 2:])))
	os.makedirs(dest, exist_ok=True)
	path = os.path.join(dest, name)
	with open(path, "wb") as fp:
		fp.write(data)
	return path


def list_models(engine: str, host: str, port: int) -> list:
	if engine == "vllm":
		url, key = f"http://{host}:{port}/v1/models", "id"
		return [m[key] for m in requests.get(url).json()["data"]]
	url = f"http://{host}:{port}/api/tags"
	return [m["model"] for m in requests.get(url).json()["models"]]


async def vllm_ttft(session, host, port, model, prompt) -> Dict[str, Any]:
	payload = {
		"model": model,
		"prompt": prompt,
		"max_tokens": 1,
		"temperature": 0.0,
		"stream": True,
		"stream_options": {"include_usage": True},
	}
	start = time.perf_counter()
	ttft = None
	usage: Dict[str, Any] = {}
	async with session.post(f"http://{host}:{port}/v1/completions", json=payload) as resp:
		if resp.status != 200:
			raise RuntimeError(f"vLLM error {resp.status}: {await resp.text()}")
		async for raw in resp.content:
			line = raw.decode("utf-8").strip()
			if not line.startswith("data:"):
				continue
			data_str = line[5:].strip()
			if not data_str or data_str == "[DONE]":
				continue
			data = json.loads(data_str)
			if ttft is None and data.get("choices"):
				ttft = time.perf_counter() - start
			if data.get("usage"):
				usage = data["usage"]
	if ttft is None:
		raise RuntimeError("no output token received")
	return {"ttft": ttft, "prompt_tokens": int(usage.get("prompt_tokens", 0)), "server_s": None}


async def ollama_ttft(session, host, port, model, prompt, num_ctx) -> Dict[str, Any]:
	options: Dict[str, Any] = {
		"num_predict": 1,
		"temperature": 0.0,
		"num_gpu": 999,  # offload all layers to GPU, prevent CPU offload
		"num_thread": 8,  # all layers are on GPU; avoid ~144 spinning CPU threads
	}
	if num_ctx:
		options["num_ctx"] = num_ctx
	payload = {"model": model, "prompt": prompt, "stream": True, "options": options}
	start = time.perf_counter()
	ttft = None
	final: Dict[str, Any] = {}
	async with session.post(f"http://{host}:{port}/api/generate", json=payload) as resp:
		if resp.status != 200:
			raise RuntimeError(f"Ollama error {resp.status}: {await resp.text()}")
		async for raw in resp.content:
			line = raw.decode("utf-8").strip()
			if not line:
				continue
			data = json.loads(line)
			if "error" in data:
				raise RuntimeError(f"Ollama error: {data['error']}")
			if ttft is None:
				ttft = time.perf_counter() - start
			if data.get("done"):
				final = data
	if ttft is None:
		raise RuntimeError("no output received")
	server_s = final.get("prompt_eval_duration", 0) / 1e9 or None
	return {"ttft": ttft, "prompt_tokens": int(final.get("prompt_eval_count", 0)), "server_s": server_s}


async def one_round(args, doc: str, model: str, parallel: int, prompt: Optional[str] = None) -> Dict[str, Any]:
	connector = aiohttp.TCPConnector(limit=parallel * 2)
	# Ollama's final chunk carries the whole prompt as a `context` token array: raise the line-size limit
	async with aiohttp.ClientSession(connector=connector, timeout=aiohttp.ClientTimeout(total=None), read_bufsize=2**26) as session:
		async def run(_):
			prompt_ = prompt if prompt is not None else build_prompt(doc)
			try:
				if args.engine == "vllm":
					r = await vllm_ttft(session, args.host, args.port, model, prompt_)
				else:
					r = await ollama_ttft(session, args.host, args.port, model, prompt_, args.num_ctx)
				r["error"] = None
			except Exception as exc:
				r = {"ttft": 0.0, "prompt_tokens": 0, "server_s": None, "error": str(exc)}
			r["chars"] = len(prompt_)
			return r

		t0 = time.perf_counter()
		results = await asyncio.gather(*[run(i) for i in range(parallel)])
		wall = time.perf_counter() - t0
	ok = [r for r in results if r["error"] is None]
	tokens = sum(r["prompt_tokens"] for r in ok)
	return {"results": results, "wall": wall, "tokens": tokens, "ok": len(ok)}


def context_limit(args, model: str) -> int:
	"""Context window the backend will actually use (0 = unknown)."""
	try:
		if args.engine == "vllm":
			for m in requests.get(f"http://{args.host}:{args.port}/v1/models").json()["data"]:
				if m["id"] == model:
					return int(m.get("max_model_len") or 0)
			return 0
		if args.num_ctx:
			return args.num_ctx
		for m in requests.get(f"http://{args.host}:{args.port}/api/ps").json().get("models", []):
			if model in (m.get("model"), m.get("name")):
				return int(m.get("context_length") or 0)
	except Exception:
		pass
	return 0


CTX_ERR = re.compile(r"context length|context window|too long|too large|exceed", re.I)
FIT_MARGIN = 0.95  # aim for this fraction of the context window
TRUNC_AT = 0.985  # Ollama silently truncates; a prompt this close to the window is treated as truncated


async def fit_document(args, doc: str, model: str):
	"""
	Find the longest prefix of `doc` that fits the context window without truncation,
	by default. vLLM rejects over-long prompts (HTTP 400) while Ollama silently truncates
	them, so: measure chars/token with a probe, pre-shrink to the window if it is known,
	then verify (vLLM: no context error; Ollama: prompt_eval_count clearly below the window)
	and shrink + resend until it fits. Doubles as the model-load warmup.
	Returns (document prefix, context limit, round to reuse as a measured round or None).
	The first full-size request is reusable (the probe already warmed the model) when it
	succeeded without any shrinking and the benchmark runs at parallel 1.
	"""
	r = (await one_round(args, doc[:20000], model, 1))["results"][0]
	if r["error"]:
		raise SystemExit(f"probe request failed: {r['error'][:500]}")
	ratio = r["chars"] / max(r["prompt_tokens"], 1)
	limit = context_limit(args, model)  # after the probe, so Ollama has loaded the model
	n = len(doc)
	if limit:
		n = min(n, int((limit - 16) * ratio * FIT_MARGIN) - len(build_prompt("")))
	elif args.engine == "ollama":
		print("⚠️  Ollama context size unknown (use --num-ctx): truncation by Ollama cannot be detected", flush=True)
	for attempt in range(12):
		n = max(n, 1000)
		rnd = await one_round(args, doc[:n], model, 1)
		r = rnd["results"][0]
		tokens = r["prompt_tokens"]
		if r["error"] and not CTX_ERR.search(r["error"]):
			raise SystemExit(f"request failed: {r['error'][:500]}")
		if not r["error"] and not (limit and tokens >= TRUNC_AT * limit):
			return doc[:n], limit, (rnd if attempt == 0 and args.parallel == 1 else None)
		# rejected, or (Ollama) truncated: shrink and resend
		if limit and tokens:
			n = int(n * FIT_MARGIN * limit / tokens)
		else:
			n = int(n * 0.9)
		print(f"  context exceeded, retrying with {n} chars", flush=True)
	raise SystemExit("could not fit the document into the context window")


def parse_args() -> argparse.Namespace:
	p = argparse.ArgumentParser(description="Pre-fill TPS benchmark (time to first token) for vLLM or Ollama")
	p.add_argument("--engine", choices=["vllm", "ollama"], default="ollama")
	p.add_argument("--host", default="localhost")
	p.add_argument("--port", type=int, help="default: 9000 for vLLM, 11434 for Ollama")
	p.add_argument("--model", default="", help="Model name as registered in the backend")
	p.add_argument("--doc", default=None, help="Markdown document to summarize (default: longest *.md in ./docs)")
	p.add_argument("--max-doc-chars", type=int, default=0, help="Cap the document at this many chars before fitting (0 = no cap)")
	p.add_argument("--parallel", type=int, default=1, help="Concurrent requests per round")
	p.add_argument("--repeats", type=int, default=1, help="Measured rounds")
	p.add_argument("--warmup", type=int, default=0, help="Extra discarded full-size rounds (the short probe in the fit step already warms the model)")
	p.add_argument("--num-ctx", type=int, default=0, help="Ollama num_ctx (0 = server default; changing it reloads the model)")
	p.add_argument("--extract-docs", nargs="?", const="docs", default=None, metavar="DIR", help="Unpack the bundled document into DIR (default ./docs) and exit")
	p.add_argument("--output", default=None, help="Write full JSON result to this file")
	return p.parse_args()


async def main():
	args = parse_args()
	if args.port is None:
		args.port = 9000 if args.engine == "vllm" else 11434

	if args.extract_docs:
		print(f"Extracted {extract_docs(args.extract_docs)}")
		return
	if args.doc is None:
		docs = sorted(glob.glob("docs/*.md"), key=os.path.getsize, reverse=True)
		args.doc = docs[0] if docs else extract_docs("docs")
	with open(args.doc, encoding="utf-8") as fp:
		doc = fp.read()
	if args.max_doc_chars:
		doc = doc[: args.max_doc_chars]

	models = list_models(args.engine, args.host, args.port)
	model = args.model if args.model in models else models[0]

	# model load / first-time lag: 1 input token ("hi"), wait for 1 output token
	print("Loading model (hi -> 1 token)...", flush=True)
	r = (await one_round(args, "", model, 1, prompt="hi"))["results"][0]
	if r["error"]:
		raise SystemExit(f"warmup request failed: {r['error'][:500]}")

	full_chars = len(doc)
	print("Fitting document to the context window...", flush=True)
	doc, limit, reused = await fit_document(args, doc, model)
	print(f"  using {len(doc)}/{full_chars} chars of the document", flush=True)

	print(f"Warming up ({args.warmup} round(s), discarded)...", flush=True)
	for _ in range(args.warmup):
		await one_round(args, doc, model, args.parallel)

	rounds = []
	if reused:
		rounds.append(reused)
		print(f"  round 1: {reused['ok']}/1 ok, wall {reused['wall']:.2f}s (fit request reused)", flush=True)
	for i in range(len(rounds), args.repeats):
		r = await one_round(args, doc, model, args.parallel)
		rounds.append(r)
		print(f"  round {i + 1}: {r['ok']}/{args.parallel} ok, wall {r['wall']:.2f}s", flush=True)

	good = [r for r in rounds if r["ok"]]
	errors = sorted({x["error"] for r in rounds for x in r["results"] if x["error"]})
	ttfts = [x["ttft"] for r in good for x in r["results"] if x["error"] is None]
	ptoks = [x["prompt_tokens"] for r in good for x in r["results"] if x["error"] is None]
	server = [x["server_s"] for r in good for x in r["results"] if x["error"] is None and x["server_s"]]
	chars = len(build_prompt(doc))
	# aggregate prefill TPS per round = tokens processed / round wall time
	agg = [r["tokens"] / r["wall"] for r in good]

	print("\n=== Prefill Summary ===")
	print(f"Engine                 : {args.engine}")
	print(f"Host / port            : {args.host}:{args.port}")
	print(f"Model                  : {model}")
	print(f"Document               : {args.doc} ({len(doc)}/{full_chars} chars used{', truncated to fit' if len(doc) < full_chars else ''})")
	print(f"Context window         : {limit or 'unknown'} tokens")
	print(f"Parallelism            : {args.parallel}")
	print(f"Rounds (measured)      : {len(good)}/{args.repeats} (+{args.warmup} warmup)")
	if ptoks:
		pt = statistics.mean(ptoks)
		print(f"Prompt tokens (actual) : {pt:.0f}  (~{chars / pt:.2f} chars/token)")
		print(f"TTFT mean/min/max (s)  : {statistics.mean(ttfts):.3f}/{min(ttfts):.3f}/{max(ttfts):.3f}")
		print("(TPS below = actual server-reported prompt tokens / time)")
		print(f"Prefill TPS (per req)  : {statistics.mean(p / t for p, t in zip(ptoks, ttfts)):.1f} tokens/s")
		print(f"Prefill TPS (aggregate): {statistics.mean(agg):.1f} tokens/s")
		if server:
			print(f"Server-side prefill TPS: {pt / statistics.mean(server):.1f} tokens/s (Ollama prompt_eval_duration)")
	if errors:
		print("\n⚠️  Some requests failed:")
		for e in errors:
			print(f"  - {e[:500]}")

	if args.output:
		with open(args.output, "w", encoding="utf-8") as fp:
			json.dump({"args": vars(args), "model": model, "rounds": rounds}, fp, indent=2)
		print(f"\nFull result written to {args.output}")


if __name__ == "__main__":
	try:
		asyncio.run(main())
	except KeyboardInterrupt:
		print("\nBenchmark interrupted by user.")


